-- Per-boss, per-spec UTILITY casts in the top Heroic-10 and Normal-10 kills of each
-- MoP Classic spec on Siege of Orgrimmar, plus lust timing. Same shape as
-- Data/BossCasts_Raid.lua (raid kind), read by Notes/Tracker.lua:
--   put(instance, boss, n, lust, specs)
--   lust   { n=, at= }  median first lust as a fraction of the fight, every logged kill
--   specs  [specID] = { n=, s = { { name, kind, cpf, share }, ... } }
--          cpf = median casts per player-fight, share = fraction of the spec's fights
--          with a cast; kind = kick dispel purge soothe stun lust defensive healercd utility
-- Built 2026-09-16 by the one-off spec research crawl (Josh 2026-09-16); 7 fights per
-- boss per spec. Not part of the monthly data refresh.
local _, TP = ...
TP.BossCasts = TP.BossCasts or {}
local B = TP.BossCasts
local function put(instance, boss, n, lust, specs)
	B[instance] = B[instance] or {}
	B[instance][boss] = { n = n, lust = lust, specs = specs }
end

